// Evalua la salida de Transformacion/ejecutar_proceso.py y resume el resultado.
// Falla la ejecucion si el codigo de salida no es 0, si falta el Excel o si la verificacion no es OK.
const EXIGIR_INGESTA = false;
const resultados = [];
for (const item of $input.all()) {
  const stdout = String(item.json.stdout || '');
  const lineas = stdout.split('\n');
  const coincidencia = stdout.match(/CODIGO_SALIDA=(\d+)\s*$/);
  const codigo = coincidencia ? Number(coincidencia[1]) : null;
  const buscar = (prefijo) => lineas.find((l) => l.startsWith(prefijo)) || '';
  const modo = buscar('=== MODO');
  const ingesta = buscar('Ingesta correcta:').replace('Ingesta correcta:', '').trim();
  const verificacion = buscar('Verificacion:');
  const excel = buscar('Excel generado:').replace('Excel generado:', '').trim();
  const csv = lineas.filter((l) => l.trim().startsWith('- Ingesta/output/')).map((l) => l.trim().slice(2));
  const posIngesta = ingesta ? stdout.indexOf('Ingesta correcta:') : -1;
  const posExcel = excel ? stdout.indexOf('Excel generado:') : -1;

  const problemas = [];
  if (codigo !== 0) problemas.push(`el proceso termino con codigo ${codigo}`);
  if (EXIGIR_INGESTA && !ingesta) problemas.push('no se confirmo una ingesta correcta');
  if (EXIGIR_INGESTA && ingesta && excel && posIngesta > posExcel) problemas.push('el Excel aparece antes que la ingesta');
  if (!excel) problemas.push('no se genero Excel');
  if (!verificacion.startsWith('Verificacion: OK')) problemas.push('la verificacion no es OK');
  if (problemas.length) {
    const detalle = lineas.filter((l) => /ERROR|FALLO|faltan valores|Verificacion|marcado para revision/.test(l)).join('\n');
    throw new Error(`No hay un Excel valido de esta ejecucion: ${problemas.join('; ')}.\n` + (detalle || stdout.slice(-2000)));
  }
  const nombre = excel.split('/').pop();
  resultados.push({
    json: {
      modo,
      ingesta_csv_nuevo: ingesta || '(no aplica: demostracion con CSV existentes)',
      excel_nombre: nombre,
      excel_ruta_en_el_repositorio: excel,
      verificacion,
      csv_consolidados: csv,
      codigo_salida: codigo,
    },
  });
}
return resultados;
